-- Atualizacoes de disponibilidade (abrigo: vagas; demais: situacao)
INSERT INTO T_CIVIA_ATUALIZACAO_DISP (ID_SERVICO, VAGAS, SITUACAO, DATA_HORA)
SELECT ID_SERVICO, 6, NULL, CAST(SYSTIMESTAMP AT TIME ZONE '-03:00' AS TIMESTAMP) - INTERVAL '20' MINUTE
  FROM T_CIVIA_SERVICO WHERE NOME = 'Centro de Acolhida Liberdade (simulado)';
INSERT INTO T_CIVIA_ATUALIZACAO_DISP (ID_SERVICO, VAGAS, SITUACAO, DATA_HORA)
SELECT ID_SERVICO, 2, NULL, CAST(SYSTIMESTAMP AT TIME ZONE '-03:00' AS TIMESTAMP) - INTERVAL '45' MINUTE
  FROM T_CIVIA_SERVICO WHERE NOME = 'Casa de Acolhida Mulheres Se (simulado)';
INSERT INTO T_CIVIA_ATUALIZACAO_DISP (ID_SERVICO, VAGAS, SITUACAO, DATA_HORA)
SELECT ID_SERVICO, 0, NULL, CAST(SYSTIMESTAMP AT TIME ZONE '-03:00' AS TIMESTAMP) - INTERVAL '3' HOUR
  FROM T_CIVIA_SERVICO WHERE NOME = 'Abrigo Gloria com Pets (simulado)';
INSERT INTO T_CIVIA_ATUALIZACAO_DISP (ID_SERVICO, VAGAS, SITUACAO, DATA_HORA)
SELECT ID_SERVICO, NULL, 'FILA_GRANDE', CAST(SYSTIMESTAMP AT TIME ZONE '-03:00' AS TIMESTAMP) - INTERVAL '10' MINUTE
  FROM T_CIVIA_SERVICO WHERE NOME = 'Restaurante Comunitario Se (simulado)';
INSERT INTO T_CIVIA_ATUALIZACAO_DISP (ID_SERVICO, VAGAS, SITUACAO, DATA_HORA)
SELECT ID_SERVICO, NULL, 'ABERTO', CAST(SYSTIMESTAMP AT TIME ZONE '-03:00' AS TIMESTAMP) - INTERVAL '30' MINUTE
